import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { useTheme } from '../contexts/ThemeContext';

// Neural node component for visual effects
const NeuralNode = ({ x, y, size, pulseDelay, color = 'rgba(100, 200, 255, 0.7)' }) => (
  <motion.div
    className="absolute rounded-full pointer-events-none"
    style={{
      left: `${x}%`,
      top: `${y}%`,
      width: `${size}px`,
      height: `${size}px`,
      backgroundColor: color,
      filter: 'blur(0.5px)',
      zIndex: 10
    }}
    initial={{ opacity: 0 }}
    animate={{ 
      opacity: [0.3, 0.9, 0.3],
      boxShadow: [
        `0 0 2px ${color}`,
        `0 0 8px ${color}`,
        `0 0 2px ${color}`
      ]
    }}
    transition={{
      duration: 2,
      repeat: Infinity,
      delay: pulseDelay
    }}
  />
);

// Circuit connection between nodes
const CircuitConnection = ({ x1, y1, x2, y2, color = 'rgba(100, 200, 255, 0.5)', delay = 0 }) => {
  // Create a zigzag path for more circuit-like look
  const midX = (x1 + x2) / 2;
  
  return (
    <motion.div 
      className="absolute top-0 left-0 w-full h-full pointer-events-none"
      style={{ zIndex: 5 }}
    >
      <svg width="100%" height="100%" className="absolute inset-0">
        <motion.path
          d={`M ${x1}% ${y1}% L ${midX}% ${y1}% L ${midX}% ${y2}% L ${x2}% ${y2}%`}
          stroke={color}
          strokeWidth="1"
          fill="none"
          strokeDasharray="3,2"
          initial={{ pathLength: 0, opacity: 0 }}
          animate={{ 
            pathLength: [0, 1],
            opacity: [0.3, 0.7, 0.3]
          }}
          transition={{ 
            duration: 2.5, 
            repeat: Infinity,
            repeatType: "reverse",
            delay
          }}
        />
      </svg>
    </motion.div>
  );
};

const BookPageFlip = ({ pages = [] }) => {
  const { theme } = useTheme();
  const [currentPage, setCurrentPage] = useState(0);
  const [direction, setDirection] = useState(null);
  const [isFlipping, setIsFlipping] = useState(false);
  
  // Sample pages for demo if none provided
  const demoPages = [
    {
      id: 1,
      title: "Introduction to Study Techniques",
      content: "Effective studying starts with the right approach. The techniques outlined in this book will help you optimize your learning process and maximize retention.",
      image: "https://via.placeholder.com/600x350/3B82F6/FFFFFF?text=Introduction"
    },
    {
      id: 2,
      title: "Active Recall",
      content: "Active recall is the practice of actively stimulating memory during the learning process. It's one of the most effective techniques for moving information from short-term to long-term memory.",
      image: "https://via.placeholder.com/600x350/F59E0B/FFFFFF?text=Active+Recall"
    },
    {
      id: 3,
      title: "Spaced Repetition",
      content: "Spaced repetition involves reviewing information at increasing intervals. This technique leverages the psychological spacing effect, which demonstrates that information is more effectively recalled when reviewed over time.",
      image: "https://via.placeholder.com/600x350/10B981/FFFFFF?text=Spaced+Repetition"
    },
    {
      id: 4,
      title: "Note-Taking Systems",
      content: "Effective note-taking is crucial for information retention. Systems like Cornell Notes, Mind Mapping, and the Outline Method each offer unique advantages depending on the subject matter and your learning style.",
      image: "https://via.placeholder.com/600x350/8B5CF6/FFFFFF?text=Note-Taking"
    }
  ];
  
  const bookPages = pages.length > 0 ? pages : demoPages;
  const totalPages = bookPages.length;
  
  const pageVariants = {
    enter: (direction) => {
      return {
        x: direction > 0 ? 1000 : -1000,
        opacity: 0,
        rotateY: direction > 0 ? -45 : 45,
        boxShadow: "0px 0px 0px rgba(0, 0, 0, 0.2)"
      };
    },
    center: {
      zIndex: 1,
      x: 0,
      opacity: 1,
      rotateY: 0,
      boxShadow: "0px 10px 20px rgba(0, 0, 0, 0.2)"
    },
    exit: (direction) => {
      return {
        zIndex: 0,
        x: direction < 0 ? 1000 : -1000,
        opacity: 0,
        rotateY: direction < 0 ? -45 : 45,
        boxShadow: "0px 0px 0px rgba(0, 0, 0, 0.2)"
      };
    }
  };

  const paginate = (newDirection) => {
    if (isFlipping) return;
    
    setIsFlipping(true);
    setDirection(newDirection);
    
    if (newDirection > 0) {
      setCurrentPage((prevPage) => (prevPage + 1) % totalPages);
    } else {
      setCurrentPage((prevPage) => (prevPage - 1 + totalPages) % totalPages);
    }
    
    // Reset flipping state after animation completes
    setTimeout(() => {
      setIsFlipping(false);
    }, 500); // Match this with the animation duration
  };

  // Keyboard navigation
  useEffect(() => {
    const handleKeyDown = (e) => {
      if (e.key === 'ArrowRight') {
        paginate(1);
      } else if (e.key === 'ArrowLeft') {
        paginate(-1);
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isFlipping]);

  return (
    <div className="relative">
      {/* Neural background grid */}
      <div className="absolute inset-0 pointer-events-none opacity-10" 
        style={{
          backgroundImage: 'linear-gradient(to right, rgba(100, 200, 255, 0.2) 1px, transparent 1px), linear-gradient(to bottom, rgba(100, 200, 255, 0.2) 1px, transparent 1px)',
          backgroundSize: '20px 20px',
          zIndex: 0
        }}
      />
      
      {/* Neural nodes in background */}
      {[...Array(8)].map((_, i) => {
        const x = 10 + Math.random() * 80;
        const y = 10 + Math.random() * 80;
        return (
          <NeuralNode
            key={`book-node-${i}`}
            x={x}
            y={y}
            size={2 + Math.random() * 3}
            pulseDelay={i * 0.3}
          />
        );
      })}
      
      {/* Circuit connections */}
      {[...Array(5)].map((_, i) => {
        const x1 = 10 + Math.random() * 40;
        const y1 = 10 + Math.random() * 80;
        const x2 = 60 + Math.random() * 30;
        const y2 = 10 + Math.random() * 80;
        
        return (
          <CircuitConnection
            key={`book-circuit-${i}`}
            x1={x1}
            y1={y1}
            x2={x2}
            y2={y2}
            delay={i * 0.2}
          />
        );
      })}
      
      {/* Scanning line */}
      <motion.div
        className="absolute left-0 right-0 h-[1px] bg-neural-400/40 pointer-events-none"
        style={{ top: '50%', zIndex: 5 }}
        animate={{
          top: ['0%', '100%'],
          opacity: [0, 0.7, 0]
        }}
        transition={{
          duration: 5,
          repeat: Infinity,
          ease: "linear"
        }}
      />
      
      {/* Book container */}
      <div className="relative perspective-1000 w-full h-[500px] overflow-hidden rounded-xl">
        <AnimatePresence initial={false} custom={direction}>
          <motion.div
            key={currentPage}
            custom={direction}
            variants={pageVariants}
            initial="enter"
            animate="center"
            exit="exit"
            transition={{
              x: { type: "spring", stiffness: 300, damping: 30 },
              opacity: { duration: 0.3 },
              rotateY: { duration: 0.5 }
            }}
            className="absolute w-full h-full bg-gray-900/70 backdrop-blur-lg flex flex-col items-center rounded-xl overflow-hidden border-2 border-neural-400/20"
            style={{ 
              transformStyle: "preserve-3d", 
              backfaceVisibility: "hidden",
              boxShadow: "0 0 20px rgba(100, 200, 255, 0.2)"
            }}
          >
            {/* Page content */}
            <div className="h-1/2 w-full relative">
              <img 
                src={bookPages[currentPage].image} 
                alt={bookPages[currentPage].title}
                className="w-full h-full object-cover"
              />
              <div className="absolute inset-0 bg-gradient-to-t from-black/70 to-transparent flex items-end">
                <h2 className="text-white text-2xl font-bold p-6 bg-clip-text text-transparent bg-gradient-to-r from-neural-200 via-white to-neural-400">
                  {bookPages[currentPage].title}
                </h2>
              </div>
              
              {/* Neural nodes for title section */}
              {[...Array(3)].map((_, i) => (
                <NeuralNode 
                  key={`title-node-${i}`}
                  x={65 + Math.random() * 30}
                  y={80 + Math.random() * 15}
                  size={2 + Math.random() * 2}
                  pulseDelay={i * 0.4}
                />
              ))}
            </div>
            
            <div className="p-6 flex-grow overflow-y-auto w-full relative">
              <p className="text-base text-white">
                {bookPages[currentPage].content}
              </p>
              
              {/* Corner circuit accents */}
              <svg className="absolute bottom-0 right-0 w-32 h-32 opacity-20 pointer-events-none" viewBox="0 0 100 100">
                <path 
                  d="M100 0 L70 0 L70 30 L60 30 L60 40 L40 40 L40 60 L30 60 L30 70 L0 70" 
                  stroke="rgba(100, 200, 255, 0.7)" 
                  strokeWidth="1" 
                  fill="none" 
                />
                <circle cx="70" cy="30" r="2" fill="rgba(100, 200, 255, 0.8)" />
                <circle cx="40" cy="60" r="2" fill="rgba(100, 200, 255, 0.8)" />
                <motion.circle 
                  cx="40" 
                  cy="60" 
                  r="4" 
                  fill="none" 
                  stroke="rgba(100, 200, 255, 0.5)" 
                  animate={{ r: [4, 8, 4], opacity: [0.5, 0.8, 0.5] }}
                  transition={{ duration: 2, repeat: Infinity }}
                />
              </svg>
            </div>
          </motion.div>
        </AnimatePresence>
      </div>
      
      {/* Navigation controls */}
      <div className="absolute bottom-6 left-0 right-0 flex justify-between px-6 z-20">
        <motion.button
          className={`w-12 h-12 rounded-full bg-neural-600 text-white flex items-center justify-center border border-neural-400/30 relative overflow-hidden ${currentPage === 0 ? 'opacity-50 cursor-not-allowed' : 'hover:bg-neural-500'}`}
          whileHover={currentPage !== 0 ? { scale: 1.1, boxShadow: "0 0 15px rgba(100, 200, 255, 0.5)" } : {}}
          whileTap={currentPage !== 0 ? { scale: 0.9 } : {}}
          onClick={() => currentPage !== 0 && paginate(-1)}
          disabled={currentPage === 0}
        >
          {/* Button circuit pattern */}
          <motion.div 
            className="absolute inset-0 opacity-30"
            style={{
              backgroundImage: 'radial-gradient(circle, rgba(100, 200, 255, 0.3) 1px, transparent 1px)',
              backgroundSize: '8px 8px'
            }}
            animate={{
              backgroundPosition: ['0% 0%', '100% 100%']
            }}
            transition={{
              duration: 10,
              repeat: Infinity,
              repeatType: "mirror"
            }}
          />
          
          <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 relative z-10" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" />
          </svg>
        </motion.button>
        
        <div className="bg-gray-900/70 px-4 py-2 rounded-full backdrop-blur-lg border border-neural-400/20 text-neural-200">
          Page {currentPage + 1} of {totalPages}
        </div>
        
        <motion.button
          className={`w-12 h-12 rounded-full bg-neural-600 text-white flex items-center justify-center border border-neural-400/30 relative overflow-hidden ${currentPage === totalPages - 1 ? 'opacity-50 cursor-not-allowed' : 'hover:bg-neural-500'}`}
          whileHover={currentPage !== totalPages - 1 ? { scale: 1.1, boxShadow: "0 0 15px rgba(100, 200, 255, 0.5)" } : {}}
          whileTap={currentPage !== totalPages - 1 ? { scale: 0.9 } : {}}
          onClick={() => currentPage !== totalPages - 1 && paginate(1)}
          disabled={currentPage === totalPages - 1}
        >
          {/* Button circuit pattern */}
          <motion.div 
            className="absolute inset-0 opacity-30"
            style={{
              backgroundImage: 'radial-gradient(circle, rgba(100, 200, 255, 0.3) 1px, transparent 1px)',
              backgroundSize: '8px 8px'
            }}
            animate={{
              backgroundPosition: ['0% 0%', '100% 100%']
            }}
            transition={{
              duration: 10,
              repeat: Infinity,
              repeatType: "mirror"
            }}
          />
          
          <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 relative z-10" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" />
          </svg>
        </motion.button>
      </div>
      
      {/* Page-turning gesture indicators */}
      <div
        className="absolute left-0 top-0 h-full w-1/3 cursor-pointer z-10 flex items-center justify-start opacity-0 hover:opacity-100 transition-opacity"
        onClick={() => currentPage !== 0 && paginate(-1)}
      >
        {currentPage !== 0 && (
          <div className="bg-neural-600/20 h-16 w-8 rounded-r-full flex items-center justify-center backdrop-blur-sm border-y border-r border-neural-400/30">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 text-neural-200" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" />
            </svg>
          </div>
        )}
      </div>
      
      <div
        className="absolute right-0 top-0 h-full w-1/3 cursor-pointer z-10 flex items-center justify-end opacity-0 hover:opacity-100 transition-opacity"
        onClick={() => currentPage !== totalPages - 1 && paginate(1)}
      >
        {currentPage !== totalPages - 1 && (
          <div className="bg-neural-600/20 h-16 w-8 rounded-l-full flex items-center justify-center backdrop-blur-sm border-y border-l border-neural-400/30">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 text-neural-200" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" />
            </svg>
          </div>
        )}
      </div>
    </div>
  );
};

export default BookPageFlip; 