import React, { useState, useEffect, useRef } from 'react';
import * as pdfjsLib from 'pdfjs-dist';
import { motion, AnimatePresence } from 'framer-motion';
import { useTheme } from '../contexts/ThemeContext';
import { useSwipeable } from 'react-swipeable';

// Set up PDF.js worker
pdfjsLib.GlobalWorkerOptions.workerSrc = `//cdnjs.cloudflare.com/ajax/libs/pdf.js/${pdfjsLib.version}/pdf.worker.min.js`;

const PDFViewer = ({ pdfPath, bookTitle }) => {
  const { theme } = useTheme();
  const [pdf, setPdf] = useState(null);
  const [currentPage, setCurrentPage] = useState(1);
  const [totalPages, setTotalPages] = useState(0);
  const [scale, setScale] = useState(1.2);
  const [error, setError] = useState(null);
  const [pageDirection, setPageDirection] = useState(0);
  const [pageUrls, setPageUrls] = useState({});
  const [isLoading, setIsLoading] = useState(true);
  const [showPlaceholder, setShowPlaceholder] = useState(false);
  const [showDebug, setShowDebug] = useState(false);
  const [debugInfo, setDebugInfo] = useState({});
  const containerRef = useRef(null);
  
  // Function to render a page to the cache
  const renderPageToCache = async (pdfDoc, pageNum, cache) => {
    if (!pdfDoc) return null;
    
    try {
      const page = await pdfDoc.getPage(pageNum);
      const viewport = page.getViewport({ scale: 1.0 });
      
      // Create an offscreen canvas
      const canvas = document.createElement('canvas');
      canvas.height = viewport.height;
      canvas.width = viewport.width;
      
      // Render to the canvas
      const renderContext = {
        canvasContext: canvas.getContext('2d'),
        viewport: viewport
      };
      
      await page.render(renderContext).promise;
      
      // Store the rendered page as a data URL
      const pageUrl = canvas.toDataURL('image/png');
      cache[pageNum] = pageUrl;
      
      return pageUrl;
    } catch (err) {
      console.error(`Error rendering page ${pageNum}:`, err);
      return null;
    }
  };
  
  // Fix PDF URL if needed (handle file:// protocol, spaces, etc.)
  const fixPdfUrl = (url) => {
    if (!url) return url;
    
    // Debugging
    let debugData = { original: url };
    
    // Handle file:// protocol issues
    let fixed = url;
    
    // Handle spaces in URLs
    if (fixed.includes(' ')) {
      fixed = fixed.replace(/ /g, '%20');
      debugData.spacesFixed = true;
    }
    
    // Handle backslashes (Windows paths)
    if (fixed.includes('\\')) {
      fixed = fixed.replace(/\\/g, '/');
      debugData.backslashesFixed = true;
    }
    
    // Check if URL starts with file:// and adjust if needed
    if (!fixed.startsWith('http') && !fixed.startsWith('file://') && !fixed.startsWith('blob:') && !fixed.startsWith('data:')) {
      // For relative paths
      if (!fixed.startsWith('/')) {
        fixed = '/' + fixed;
        debugData.relativePathFixed = true;
      }
      fixed = 'file://' + fixed;
      debugData.protocolAdded = true;
    }
    
    debugData.fixed = fixed;
    setDebugInfo(prevInfo => ({ ...prevInfo, url: debugData }));
    
    return fixed;
  };
  
  // Load the PDF document
  useEffect(() => {
    let loadingTask = null;
    let isMounted = true;
    
    async function loadPDF() {
      try {
        setError(null);
        setIsLoading(true);
        setShowPlaceholder(false);
        
        // Handle case when pdfPath is not provided
        if (!pdfPath) {
          if (isMounted) {
            setShowPlaceholder(true);
            setError("No PDF document specified");
            setIsLoading(false);
          }
          return;
        }
        
        // Fix and prepare PDF URL
        const fixedPdfUrl = fixPdfUrl(pdfPath);
        console.log("Loading PDF from path:", fixedPdfUrl);
        
        // Add to debug info
        setDebugInfo(prevInfo => ({
          ...prevInfo,
          pdfDetails: {
            originalPath: pdfPath,
            fixedPath: fixedPdfUrl,
            timestamp: new Date().toISOString()
          }
        }));
        
        // Load the PDF
        loadingTask = pdfjsLib.getDocument({
          url: fixedPdfUrl,
          cMapUrl: 'https://cdn.jsdelivr.net/npm/pdfjs-dist@2.16.105/cmaps/',
          cMapPacked: true,
          // Increase timeout for large PDFs
          isEvalSupported: true,
          disableStream: false,
          disableAutoFetch: false,
          disableRange: false
        });
        
        loadingTask.onProgress = (progress) => {
          const percent = Math.round(progress.loaded / (progress.total || 1) * 100);
          console.log("PDF loading progress:", percent + "%");
          
          // Update debug info with progress
          setDebugInfo(prevInfo => ({
            ...prevInfo,
            loadProgress: {
              percent,
              loaded: progress.loaded,
              total: progress.total || 'unknown'
            }
          }));
        };
        
        const loadedPdf = await loadingTask.promise;
        console.log("PDF loaded successfully with", loadedPdf.numPages, "pages");
        
        if (!isMounted) return;
        
        setPdf(loadedPdf);
        setTotalPages(loadedPdf.numPages);
        setCurrentPage(1);
        
        // Update debug info with success
        setDebugInfo(prevInfo => ({
          ...prevInfo,
          pdfLoaded: {
            success: true,
            numPages: loadedPdf.numPages,
            timestamp: new Date().toISOString()
          }
        }));
        
        // Pre-render the first 3 pages for smooth transitions
        if (loadedPdf.numPages > 0) {
          const pageCache = {};
          
          // Render first page
          const page1Url = await renderPageToCache(loadedPdf, 1, pageCache);
          console.log("First page rendered:", !!page1Url);
          
          // Render second page if it exists
          if (loadedPdf.numPages > 1) {
            const page2Url = await renderPageToCache(loadedPdf, 2, pageCache);
            console.log("Second page rendered:", !!page2Url);
          }
          
          if (isMounted) {
            setPageUrls(pageCache);
            setIsLoading(false);
            
            // Update debug info with rendering success
            setDebugInfo(prevInfo => ({
              ...prevInfo,
              rendering: {
                success: true,
                pagesRendered: Object.keys(pageCache).length,
                timestamp: new Date().toISOString()
              }
            }));
          }
        }
      } catch (err) {
        if (isMounted) {
          console.error('Error loading PDF:', err);
          setError(`Failed to load PDF: ${err.message}`);
          setIsLoading(false);
          
          // Update debug info with error
          setDebugInfo(prevInfo => ({
            ...prevInfo,
            error: {
              message: err.message,
              name: err.name,
              stack: err.stack,
              timestamp: new Date().toISOString()
            }
          }));
          
          // Show detailed error for debugging
          if (err.name === 'MissingPDFException') {
            setError('PDF not found. Please check if the file exists.');
          } else if (err.name === 'InvalidPDFException') {
            setError('Invalid or corrupted PDF file.');
          } else if (err.name === 'PasswordException') {
            setError('PDF is password protected.');
          } else if (err.message && err.message.includes('CORS')) {
            setError('CORS issue: Cannot access PDF across different domains. Try a local file.');
          }
        }
      }
    }
    
    loadPDF();
    
    return () => {
      isMounted = false;
      if (loadingTask) {
        loadingTask.destroy().catch(err => console.error('Error destroying PDF task:', err));
      }
    };
  }, [pdfPath]);
  
  // Preload the next page when needed
  useEffect(() => {
    if (!pdf || !currentPage) return;
    
    async function preloadAdjacentPages() {
      // Preload next page
      if (currentPage < totalPages && !pageUrls[currentPage + 1]) {
        await renderPageToCache(pdf, currentPage + 1, {...pageUrls});
        setPageUrls(prev => ({...prev}));
      }
      
      // Preload previous page
      if (currentPage > 1 && !pageUrls[currentPage - 1]) {
        await renderPageToCache(pdf, currentPage - 1, {...pageUrls});
        setPageUrls(prev => ({...prev}));
      }
    }
    
    preloadAdjacentPages();
  }, [pdf, currentPage, totalPages, pageUrls]);
  
  // Functions for page and zoom control
  const changePage = (delta) => {
    const newPage = currentPage + delta;
    if (newPage >= 1 && newPage <= totalPages) {
      setPageDirection(delta);
      setCurrentPage(newPage);
    }
  };
  
  const changeZoom = (delta) => {
    const newScale = Math.max(0.5, Math.min(3, scale + delta));
    setScale(newScale);
  };
  
  // Page flip animation variants
  const pageVariants = {
    enter: (direction) => ({
      x: direction > 0 ? "100%" : "-100%",
      opacity: 0,
      rotateY: direction > 0 ? -20 : 20,
      boxShadow: "0px 0px 0px rgba(0, 0, 0, 0.2)"
    }),
    center: {
      x: 0,
      opacity: 1,
      rotateY: 0,
      boxShadow: "0px 10px 30px rgba(0, 0, 0, 0.3)"
    },
    exit: (direction) => ({
      x: direction < 0 ? "100%" : "-100%",
      opacity: 0,
      rotateY: direction < 0 ? -20 : 20,
      boxShadow: "0px 0px 0px rgba(0, 0, 0, 0.2)"
    })
  };
  
  // Handle swipe gestures
  const swipeHandlers = useSwipeable({
    onSwipedLeft: () => changePage(1),
    onSwipedRight: () => changePage(-1),
    preventDefaultTouchmoveEvent: true,
    trackMouse: false,
    trackTouch: true,
    delta: 10, // Lower threshold for swipe detection
    swipeDuration: 500, // Allow slower swipes
  });

  // Handle keyboard navigation
  useEffect(() => {
    const handleKeyDown = (e) => {
      if (e.key === 'ArrowRight') {
        changePage(1);
      } else if (e.key === 'ArrowLeft') {
        changePage(-1);
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [currentPage, totalPages, changePage]);
  
  // Resize handling for responsiveness
  useEffect(() => {
    const handleResize = () => {
      if (containerRef.current) {
        const containerWidth = containerRef.current.clientWidth;
        const containerHeight = containerRef.current.clientHeight;
        // More responsive scaling based on both dimensions
        const isMobile = window.innerWidth < 768;
        // Use smaller scale on mobile for better fit
        const newScale = isMobile 
          ? Math.min(0.9, (containerWidth / 600) * 0.9, (containerHeight / 800) * 0.9) 
          : Math.min(1.2, containerWidth / 600);
        setScale(newScale);
      }
    };
    
    handleResize(); // Call once to initialize
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  // Add touch gesture handling for pinch zoom
  useEffect(() => {
    if (!containerRef.current) return;
    
    let initialDistance = 0;
    let initialScale = scale;
    
    const handleTouchStart = (e) => {
      if (e.touches.length === 2) {
        // Get initial distance between two fingers
        initialDistance = Math.hypot(
          e.touches[0].clientX - e.touches[1].clientX,
          e.touches[0].clientY - e.touches[1].clientY
        );
        initialScale = scale;
      }
    };
    
    const handleTouchMove = (e) => {
      if (e.touches.length === 2) {
        // Calculate new distance
        const newDistance = Math.hypot(
          e.touches[0].clientX - e.touches[1].clientX,
          e.touches[0].clientY - e.touches[1].clientY
        );
        
        // Calculate scale factor based on distance change
        const scaleFactor = newDistance / initialDistance;
        const newScale = Math.max(0.5, Math.min(3, initialScale * scaleFactor));
        
        setScale(newScale);
        e.preventDefault(); // Prevent default pinch zoom
      }
    };
    
    const container = containerRef.current;
    container.addEventListener('touchstart', handleTouchStart, { passive: false });
    container.addEventListener('touchmove', handleTouchMove, { passive: false });
    
    return () => {
      container.removeEventListener('touchstart', handleTouchStart);
      container.removeEventListener('touchmove', handleTouchMove);
    };
  }, [scale]);

  // Render placeholder when no PDF is specified
  if (showPlaceholder) {
    return (
      <div className="flex flex-col items-center justify-center h-full p-8 text-center relative overflow-hidden">
        {/* Neural background grid */}
        <div className="absolute inset-0 pointer-events-none opacity-10" 
          style={{
            backgroundImage: 'linear-gradient(to right, rgba(100, 200, 255, 0.2) 1px, transparent 1px), linear-gradient(to bottom, rgba(100, 200, 255, 0.2) 1px, transparent 1px)',
            backgroundSize: '20px 20px',
            zIndex: 0
          }}
        />
        
        {/* Neural nodes */}
        {[...Array(6)].map((_, i) => (
          <motion.div
            key={`pdf-node-${i}`}
            className="absolute rounded-full pointer-events-none"
            style={{
              left: `${10 + Math.random() * 80}%`,
              top: `${10 + Math.random() * 80}%`,
              width: `${2 + Math.random() * 4}px`,
              height: `${2 + Math.random() * 4}px`,
              backgroundColor: 'rgba(100, 200, 255, 0.7)',
              filter: 'blur(0.5px)',
              zIndex: 10
            }}
            initial={{ opacity: 0 }}
            animate={{ 
              opacity: [0.3, 0.9, 0.3],
              boxShadow: [
                '0 0 2px rgba(100, 200, 255, 0.7)',
                '0 0 8px rgba(100, 200, 255, 0.7)',
                '0 0 2px rgba(100, 200, 255, 0.7)'
              ]
            }}
            transition={{
              duration: 2,
              repeat: Infinity,
              delay: i * 0.3
            }}
          />
        ))}
        
        {/* Circuit connections with sharper angles */}
        {[...Array(4)].map((_, i) => {
          // Generate random circuit paths with sharp angles
          const startX = 20 + Math.random() * 30;
          const startY = 20 + Math.random() * 60;
          const midX1 = 40 + Math.random() * 10;
          const midY1 = startY;
          const midX2 = midX1;
          const midY2 = 40 + Math.random() * 20;
          const midX3 = 60 + Math.random() * 10;
          const midY3 = midY2;
          const endX = 70 + Math.random() * 20;
          const endY = 40 + Math.random() * 50;
          
          return (
            <svg key={`pdf-circuit-${i}`} className="absolute inset-0 w-full h-full pointer-events-none" style={{ zIndex: 5 }}>
              <motion.path
                d={`M ${startX}% ${startY}% H ${midX1}% V ${midY2}% H ${midX3}% L ${endX}% ${endY}%`}
                stroke="rgba(100, 200, 255, 0.5)"
                strokeWidth="1"
                fill="none"
                strokeDasharray="4,2"
                initial={{ pathLength: 0, opacity: 0 }}
                animate={{ 
                  pathLength: [0, 1],
                  opacity: [0.3, 0.7, 0.3]
                }}
                transition={{ 
                  duration: 2.5, 
                  repeat: Infinity,
                  repeatType: "reverse",
                  delay: i * 0.4
                }}
              />
            </svg>
          );
        })}
        
        {/* Scanning line */}
        <motion.div
          className="absolute left-0 right-0 h-[1px] bg-blue-400/40 pointer-events-none"
          style={{ top: '50%', zIndex: 5 }}
          animate={{
            top: ['0%', '100%'],
            opacity: [0, 0.7, 0]
          }}
          transition={{
            duration: 5,
            repeat: Infinity,
            ease: "linear"
          }}
        />
        
        <motion.div 
          className="bg-gray-900/70 backdrop-blur-lg p-8 rounded-xl border-2 border-blue-400/20 relative overflow-hidden max-w-md"
          initial={{ scale: 0.9, opacity: 0 }}
          animate={{ scale: 1, opacity: 1 }}
          transition={{ duration: 0.5 }}
        >
          {/* Circuit accent in corner with sharper angles */}
          <svg className="absolute top-0 right-0 w-24 h-24 opacity-20 pointer-events-none" viewBox="0 0 100 100">
            <path 
              d="M100 0 L70 0 L70 30 L60 30 L60 40 L40 40 L40 60 L30 60 L30 70 L0 70" 
              stroke="rgba(100, 200, 255, 0.7)" 
              strokeWidth="1" 
              fill="none" 
              strokeDasharray="2,1"
            />
            <circle cx="70" cy="30" r="2" fill="rgba(100, 200, 255, 0.8)" />
            <circle cx="40" cy="60" r="2" fill="rgba(100, 200, 255, 0.8)" />
            <motion.circle 
              cx="40" 
              cy="60" 
              r="4" 
              fill="none" 
              stroke="rgba(100, 200, 255, 0.5)" 
              animate={{ r: [4, 8, 4], opacity: [0.5, 0.8, 0.5] }}
              transition={{ duration: 2, repeat: Infinity }}
            />
          </svg>
          
          <div className="p-3 bg-blue-600/20 rounded-full inline-block mb-4 border border-blue-400/30 relative">
            <motion.div 
              className="absolute inset-0 rounded-full"
              animate={{ 
                boxShadow: [
                  "0 0 0px rgba(100, 200, 255, 0.3)", 
                  "0 0 20px rgba(100, 200, 255, 0.6)",
                  "0 0 0px rgba(100, 200, 255, 0.3)"
                ]
              }}
              transition={{ duration: 2, repeat: Infinity }}
            />
            <svg xmlns="http://www.w3.org/2000/svg" className="h-10 w-10 text-blue-300" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 6.253v13m0-13C10.832 5.477 9.246 5 7.5 5S4.168 5.477 3 6.253v13C4.168 18.477 5.754 18 7.5 18s3.332.477 4.5 1.253m0-13C13.168 5.477 14.754 5 16.5 5c1.747 0 3.332.477 4.5 1.253v13C19.832 18.477 18.247 18 16.5 18c-1.746 0-3.332.477-4.5 1.253" />
            </svg>
          </div>
          
          <h2 className="text-xl font-semibold mb-3 text-transparent bg-clip-text bg-gradient-to-r from-blue-200 via-white to-blue-400">
            No document selected
          </h2>
          
          <div className="mb-5 space-y-2">
            <p className="text-blue-100 max-w-lg">
              Please select a book from your library to view its contents here.
            </p>
            <p className="text-blue-200/70 max-w-lg text-sm">
              कृपया अपनी लाइब्रेरी से एक किताब चुनें
            </p>
            <p className="text-blue-200/70 max-w-lg text-sm">
              अपनी लाइब्रेरी से पुस्तक का चयन करें
            </p>
          </div>
          
          {/* Add a circuit path decorative element */}
          <svg className="absolute bottom-0 left-0 w-full h-12 opacity-20 pointer-events-none" preserveAspectRatio="none">
            <path 
              d="M0 12 H 20 V 8 H 40 V 12 H 60 V 6 H 80 V 10 H 100"
              stroke="rgba(100, 200, 255, 0.7)" 
              strokeWidth="1"
              fill="none"
              strokeDasharray="1,1"
            />
          </svg>
          
          <motion.div 
            className="inline-block rounded-full bg-blue-600/20 border border-blue-400/30 p-1"
            animate={{ 
              boxShadow: [
                "0 0 0px rgba(100, 200, 255, 0.2)", 
                "0 0 10px rgba(100, 200, 255, 0.4)",
                "0 0 0px rgba(100, 200, 255, 0.2)"
              ]
            }}
            transition={{ duration: 2, repeat: Infinity }}
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 text-blue-300" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" />
            </svg>
          </motion.div>
        </motion.div>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-full">
      {/* Header with controls - make more touch-friendly on mobile */}
      <div className="flex flex-col md:flex-row md:items-center justify-between mb-3 md:mb-5 gap-2">
        <h3 className={`text-lg font-medium ${theme.text.primary} truncate max-w-full md:max-w-xs pl-2 border-l-2 border-blue-500/30`}>
          {bookTitle || 'PDF Viewer'}
        </h3>
        
        <div className="flex items-center self-end px-2 py-1 rounded-xl bg-gray-800/50 backdrop-blur-sm border border-gray-700/30">
          {/* Page Controls - Larger touch targets */}
          <div className="flex items-center mr-3">
            <motion.button
              className="p-3 bg-gray-700/50 rounded-lg hover:bg-gray-600/50 transition-colors mr-2"
              whileTap={{ scale: 0.9 }}
              onClick={() => changePage(-1)}
              disabled={currentPage <= 1}
              aria-label="Previous page"
            >
              <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 text-blue-300" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" />
              </svg>
            </motion.button>
            
            <span className={`text-sm ${theme.text.secondary} bg-gray-800/70 px-2 py-1 rounded-md min-w-[60px] text-center`}>
              {currentPage} / {totalPages}
            </span>
            
            <motion.button
              className="p-3 bg-gray-700/50 rounded-lg hover:bg-gray-600/50 transition-colors ml-2"
              whileTap={{ scale: 0.9 }}
              onClick={() => changePage(1)}
              disabled={currentPage >= totalPages}
              aria-label="Next page"
            >
              <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 text-blue-300" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" />
              </svg>
            </motion.button>
          </div>
          
          {/* Zoom Controls - Larger touch targets */}
          <div className="flex items-center border-l border-gray-700/30 pl-3">
            <motion.button
              className="p-3 bg-gray-700/50 rounded-lg hover:bg-gray-600/50 transition-colors mr-2"
              whileTap={{ scale: 0.9 }}
              onClick={() => changeZoom(-0.1)}
              aria-label="Zoom out"
            >
              <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 text-blue-300" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M20 12H4" />
              </svg>
            </motion.button>
            
            <span className={`text-sm ${theme.text.secondary} bg-gray-800/70 px-2 py-1 rounded-md min-w-[60px] text-center`}>
              {Math.round(scale * 100)}%
            </span>
            
            <motion.button
              className="p-3 bg-gray-700/50 rounded-lg hover:bg-gray-600/50 transition-colors ml-2"
              whileTap={{ scale: 0.9 }}
              onClick={() => changeZoom(0.1)}
              aria-label="Zoom in"
            >
              <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 text-blue-300" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" />
              </svg>
            </motion.button>
          </div>
        </div>
      </div>
      
      {/* PDF Viewer Container - Improved for mobile */}
      <div 
        ref={containerRef}
        className="relative flex-grow overflow-auto rounded-xl bg-gray-800/50 touch-pan-y border border-gray-700/30 shadow-inner"
        style={{ perspectiveOrigin: "center", perspective: "1200px" }}
        {...swipeHandlers}
      >
        <div className="absolute inset-0 bg-gradient-to-br from-blue-500/5 to-indigo-600/5 -z-10"></div>
        
        {/* Guide overlay for touch gestures on mobile (shown initially) */}
        {isLoading && (
          <div className="absolute inset-0 flex items-center justify-center bg-gray-900/80 z-30 touch-none">
            <div className="text-center p-6 bg-gray-800/90 rounded-xl max-w-xs border border-gray-700/30">
              <div className="flex justify-center mb-4">
                <svg xmlns="http://www.w3.org/2000/svg" className="h-12 w-12 text-blue-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 11.5V14m0-2.5v-6a1.5 1.5 0 113 0m-3 6a1.5 1.5 0 00-3 0v2a7.5 7.5 0 0015 0v-5a1.5 1.5 0 00-3 0m-6-3V11m0-5.5v-1a1.5 1.5 0 013 0v1m0 0V11m0-5.5a1.5 1.5 0 013 0v3m0 0V11" />
                </svg>
              </div>
              <p className="text-white text-lg font-medium mb-2">Touch Controls:</p>
              <ul className="text-sm text-gray-300 space-y-2 text-left">
                <li className="flex items-center">
                  <span className="mr-2">👆</span> Swipe left/right to turn pages
                </li>
                <li className="flex items-center">
                  <span className="mr-2">👌</span> Pinch to zoom in and out
                </li>
              </ul>
            </div>
          </div>
        )}
        
        {error ? (
          <div className="flex items-center justify-center h-full p-4">
            <div className="text-center max-w-lg">
              <div className="p-3 bg-red-500/10 rounded-full inline-block mb-4 border border-red-500/30">
                <svg xmlns="http://www.w3.org/2000/svg" className="h-10 w-10 text-red-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
                </svg>
              </div>
              <p className="mb-3 text-lg font-semibold text-red-400">Error loading PDF</p>
              <p className={`${theme.text.secondary} mb-4 text-sm`}>{error}</p>
              
              <div className="flex flex-col space-y-3 mb-4 text-sm text-left bg-gray-800/50 p-4 rounded-lg border border-red-500/20">
                <p className="text-gray-300">Troubleshooting steps:</p>
                <ol className="list-decimal pl-5 text-gray-400 space-y-2">
                  <li>Check if the file path is correct</li>
                  <li>Ensure the file is a valid PDF format</li>
                  <li>Try with a different PDF file</li>
                  <li>Make sure the file isn't corrupted or password-protected</li>
                </ol>
              </div>
              
              <div className="flex space-x-3 justify-center">
                <motion.button 
                  className="px-4 py-2 bg-gradient-to-r from-blue-600 to-indigo-700 text-white rounded-lg shadow-lg border border-blue-500/30 relative overflow-hidden group"
                  whileHover={{ scale: 1.05 }}
                  whileTap={{ scale: 0.95 }}
                  onClick={() => window.location.reload()}
                >
                  <div className="absolute inset-0 bg-gradient-to-r from-blue-400/20 to-indigo-400/20 opacity-0 group-hover:opacity-100 transition-opacity duration-300"></div>
                  <span className="font-medium">Reload App</span>
                </motion.button>
                
                <motion.button 
                  className="px-4 py-2 bg-gray-700 text-white rounded-lg shadow-lg border border-gray-600/30 relative overflow-hidden group"
                  whileHover={{ scale: 1.05 }}
                  whileTap={{ scale: 0.95 }}
                  onClick={() => {
                    setError(null);
                    setIsLoading(false);
                    setShowPlaceholder(true);
                  }}
                >
                  <span className="font-medium">Go Back</span>
                </motion.button>
              </div>
            </div>
          </div>
        ) : (
          <AnimatePresence initial={false} mode="wait">
            <motion.div 
              key={currentPage}
              custom={pageDirection}
              variants={pageVariants}
              initial="enter"
              animate="center"
              exit="exit"
              transition={{
                x: { type: "spring", stiffness: 300, damping: 30 },
                opacity: { duration: 0.2 }
              }}
              className="flex justify-center min-h-full py-4 px-2"
            >
              {isLoading && !pageUrls[currentPage] ? (
                <div className="flex flex-col items-center justify-center w-full">
                  <div className="relative w-16 h-16 mb-4">
                    <div className="absolute inset-0 rounded-full border-4 border-blue-500/30 opacity-75"></div>
                    <div className="absolute inset-0 rounded-full border-4 border-transparent border-t-blue-500 animate-spin"></div>
                  </div>
                  <p className="text-blue-300 animate-pulse">Loading PDF...</p>
                  <p className="text-gray-400 text-sm mt-2">यह कुछ समय लग सकता है।</p>
                </div>
              ) : (
                <div className="relative">
                  {pageUrls[currentPage] ? (
                    <img 
                      src={pageUrls[currentPage]} 
                      alt={`Page ${currentPage}`} 
                      style={{ 
                        transform: `scale(${scale})`,
                        transformOrigin: "top center", 
                        maxWidth: "100%",
                        transition: "transform 0.2s ease" 
                      }}
                      className="shadow-xl rounded"
                      onError={(e) => {
                        console.error("Error loading page image");
                        e.target.src = 'data:image/svg+xml;base64,';
                        e.target.classList.add('error-image');
                      }}
                    />
                  ) : (
                    <div className="flex flex-col items-center justify-center p-8 rounded-lg bg-gray-800/50 border border-gray-700/50 min-w-[300px] min-h-[400px]">
                      <svg className="w-12 h-12 text-gray-500 mb-3" fill="none" stroke="currentColor" viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 6v6m0 0v6m0-6h6m-6 0H6"></path>
                      </svg>
                      <p className="text-gray-400 mb-1">No page data available</p>
                      <p className="text-gray-500 text-sm">पेज डेटा उपलब्ध नहीं है</p>
                    </div>
                  )}
                  
                  {/* Page number overlay */}
                  <div className="absolute bottom-2 right-2 bg-gray-900/80 text-white text-xs px-2 py-1 rounded-md">
                    {currentPage} / {totalPages}
                  </div>
                </div>
              )}
            </motion.div>
          </AnimatePresence>
        )}
      </div>
      
      {/* Mobile page navigation indicators */}
      <div className="md:hidden flex justify-center mt-4 space-x-1">
        <div className="flex items-center bg-gray-800/50 px-3 py-1.5 rounded-full border border-gray-700/30">
          <motion.button
            whileTap={{ scale: 0.9 }}
            onClick={() => changePage(-1)}
            disabled={currentPage <= 1}
            className="mr-2 opacity-80"
            aria-label="Previous page"
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 text-blue-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" />
            </svg>
          </motion.button>
          
          <div className="text-sm text-center text-white">
            Page <span className="font-medium text-blue-400">{currentPage}</span> of {totalPages}
          </div>
          
          <motion.button
            whileTap={{ scale: 0.9 }}
            onClick={() => changePage(1)}
            disabled={currentPage >= totalPages}
            className="ml-2 opacity-80"
            aria-label="Next page"
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 text-blue-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" />
            </svg>
          </motion.button>
        </div>
      </div>
      
      {/* Debug Panel - Hidden by default */}
      {error && (
        <div className="flex justify-end mt-2">
          <button 
            onClick={() => setShowDebug(!showDebug)}
            className="text-xs text-blue-400 bg-gray-800/50 px-2 py-1 rounded hover:bg-gray-700/50 transition-colors"
          >
            {showDebug ? "Hide" : "Show"} Debug Info
          </button>
        </div>
      )}
      
      {showDebug && (
        <div className="mt-2 p-4 bg-gray-900/80 border border-gray-700 rounded-md text-xs text-gray-300 font-mono overflow-auto max-h-48">
          <h4 className="font-semibold text-blue-300 mb-2">Debug Information</h4>
          <pre>{JSON.stringify(debugInfo, null, 2)}</pre>
        </div>
      )}
    </div>
  );
};

export default PDFViewer; 